import Foundation

/// 内置食物库：常见主食、菜、零食、饮料、快餐，每 100g 的实测/标准参考值。
/// 搜不到的东西走联网（Open Food Facts）或扫条码，那两种拿的是厂商官方数据。
struct LocalFood: Identifiable, Hashable {
    var id = UUID()
    var name: String
    var group: String
    var kcal: Double
    var protein: Double
    var carb: Double
    var fat: Double
    var fiber: Double = 0
    /// 常见一份的克数（米饭一碗 150、一个苹果 200 这种）
    var portion: Double = 100
    /// 品牌：包装零食和连锁饮品靠这个做二级匹配（只读到 logo 时用）
    var brand: String = ""
    /// 别名：包装上可能印的这些词，OCR 读到任意一个就算命中
    var aliases: [String] = []

    var macroLine: String {
        String(format: "每100g  %.0f kcal · 蛋白 %.1f · 碳水 %.1f · 脂肪 %.1f",
               kcal, protein, carb, fat)
    }
}

enum FoodBase {
    static func search(_ q: String, limit: Int = 40) -> [LocalFood] {
        let key = q.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !key.isEmpty else { return Array(items.prefix(limit)) }
        // 走统一打分：剥规格、认别名、按字覆盖排序，用户怎么说都能落到具体一款
        let ranked = FoodRank.rank(key, limit: limit)
        if !ranked.isEmpty { return ranked.map { $0.food } }
        // 兜底：分组词（"零食""饮料"）还能按组扫
        let g = key.lowercased()
        return Array(items.filter { $0.group.lowercased().contains(g) }.prefix(limit))
    }

